roles.source:
@startuml
layout horizontal
class Context {
  - state: State
  + request()
  + setState(next)
}
interface State {
  + handle(context)
}
class ConcreteState {
  + handle(context)
}
Context --> "1" State : current
ConcreteState ..|> State
ConcreteState ..> Context : setState(next)
@enduml
